contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, bool approvedBefore, address keepAddress, bytes32 digest, bytes32 r, bytes32 s, bool wasFraud, bytes32 txid) public {
        require(caller != address(this), "caller must not be the test contract itself");
        require(caller != msg.sender, "caller must differ from test owner");
        require(c.approvedToLog(caller) == approvedBefore, "provided approval flag must match actual state");

        bool r1 = c.logCreated(keepAddress); if (__ESBMC_reverted()) return;
        bool a1 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r2 = c.logRedemptionRequested(caller, digest, 0, "", 0, ""); if (__ESBMC_reverted()) return;
        bool a2 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r3 = c.logGotRedemptionSignature(digest, r, s); if (__ESBMC_reverted()) return;
        bool a3 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r4 = c.logRegisteredPubkey(bytes32(0), bytes32(0)); if (__ESBMC_reverted()) return;
        bool a4 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r5 = c.logSetupFailed(); if (__ESBMC_reverted()) return;
        bool a5 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r6 = c.logFraudDuringSetup(); if (__ESBMC_reverted()) return;
        bool a6 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r7 = c.logFunded(); if (__ESBMC_reverted()) return;
        bool a7 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r8 = c.logCourtesyCalled(); if (__ESBMC_reverted()) return;
        bool a8 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r9 = c.logStartedLiquidation(wasFraud); if (__ESBMC_reverted()) return;
        bool a9 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r10 = c.logRedeemed(txid); if (__ESBMC_reverted()) return;
        bool a10 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r11 = c.logLiquidated(); if (__ESBMC_reverted()) return;
        bool a11 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool r12 = c.logExitedCourtesyCall(); if (__ESBMC_reverted()) return;
        bool a12 = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        assert(
            r1 == approvedBefore && a1 == approvedBefore &&
            r2 == approvedBefore && a2 == approvedBefore &&
            r3 == approvedBefore && a3 == approvedBefore &&
            r4 == approvedBefore && a4 == approvedBefore &&
            r5 == approvedBefore && a5 == approvedBefore &&
            r6 == approvedBefore && a6 == approvedBefore &&
            r7 == approvedBefore && a7 == approvedBefore &&
            r8 == approvedBefore && a8 == approvedBefore &&
            r9 == approvedBefore && a9 == approvedBefore &&
            r10 == approvedBefore && a10 == approvedBefore &&
            r11 == approvedBefore && a11 == approvedBefore &&
            r12 == approvedBefore && a12 == approvedBefore
        );
    }

    receive() external payable {}
}

